CardSpoke_MODS.register('research-hub', {
  onLoad: function(ctx) {
    if (document.getElementById('mod-research-stats')) return;
    var bar = document.createElement('div');
    bar.id = 'mod-research-stats';
    document.body.appendChild(bar);
    this._updateStats = function() {
      var meta = storeAPI.getDatasetMeta();
      var cards = storeAPI.listCards();
      var totalWords = cards.reduce(function(sum, c) {
        var text = (c.title || '') + ' ' + (c.body || '');
        return sum + text.trim().split(/\s+/).filter(function(w) { return w.length > 0; }).length;
      }, 0);
      var totalTags = storeAPI.getAllTags().length;
      bar.innerHTML = '<span class="stat-item">Cards: <span class="stat-value">' + meta.cardCount + '</span></span>' +
        '<span class="stat-item">Words: <span class="stat-value">' + totalWords + '</span></span>' +
        '<span class="stat-item">Tags: <span class="stat-value">' + totalTags + '</span></span>' +
        '<span class="stat-item">Bookmarks: <span class="stat-value">' + meta.bookmarkCount + '</span></span>';
    };
    this._updateStats();
    bar.classList.add('visible');
    ctx.logger.info('Research Hub loaded');
  },
  onCardSave: function(ctx, card, saveInfo) {
    if (this._updateStats) this._updateStats();
  },
  onDisable: function(ctx) {
    var bar = document.getElementById('mod-research-stats');
    if (bar) bar.remove();
    ctx.logger.info('Research Hub disabled');
  },
  onUninstall: function(ctx) {
    var bar = document.getElementById('mod-research-stats');
    if (bar) bar.remove();
  }
});
